int remap_file_pages(
    void *addr,       // Target start address (must be in mmap region)
    size_t size,      // Length (multiple of page size)
    int prot,         // Protection flags (e.g., PROT_READ)
    size_t pgoff,     // File offset in PAGES, not bytes
    int flags         // Usually 0
);

#define PAGE_SZ 4096
void *map_ptr = (void *)0x7f000000; // Result of mmap()

// Remap page 5 of the file (pgoff=5) to memory location 1
int res = remap_file_pages(
    map_ptr + PAGE_SZ,
    PAGE_SZ,
    PROT_READ | PROT_WRITE,
    5, // Fifth page of the file
    0
);
